"""Mil, somun ve destek ailesinin müşteri içeriği ve çizim bağlamları."""
import re
from html import escape

from aile_hazirla import slug, table
from hazirla import ascii_text, tr_lower

CATEGORIES = {
    'KKM': ('KROM KAPLI İNDÜKSİYONLU MİLLER', 'krom-kapli-'),
    'IM': ('KROM KAPLI İNDÜKSİYONLU MİLLER', 'krom-kapli-'),
    'SAC': ('ALT DESTEKLİ MİLLER', 'alt-destekli-miller'),
    'TBR': ('TBR SERİSİ', 'tbr-serisi'),
    'VM': ('VİDALI MİLLER', 'vidali-miller'),
    'SFU': ('BİLYALI SOMUNLAR', 'bilyali-somunlar'),
    'DSG': ('VİDALI MİL SOMUN GÖVDESİ', 'vidali-mil-somun-govdesi'),
}
SITE = 'https://www.yamansarulman.com/'


def identity(raw):
    family, size, model = raw['aile'], raw['nominal'], raw['model']
    d = {k: v['deger'] for k, v in raw['degerler'].items()}
    if family in ['KKM', 'IM']:
        code = ('KKM ' if family == 'KKM' else 'İM ') + model
        kind = 'Krom Kaplı Mil' if family == 'KKM' else 'İndüksiyonlu Mil'
        return f'{code} {kind} {size} mm - 4 Metre', code
    if family == 'SAC':
        metres = int(d['Boy (L)'].split()[0]) // 1000
        return f'{model} Alt Destekli Mil {size} mm - {metres} Metre', model
    if family == 'TBR':
        return f'{model} Açık Flanşlı Lineer Rulman {size} mm', model
    if family == 'VM':
        return f'{model} Bilyalı Vidalı Mil {size} mm - {d["Boy (L)"]}', model
    if family == 'SFU':
        code = ('ETAZON ' if raw['marka'] == 'ETAZON' else '') + model
        return f'{code} Bilyalı Vidalı Mil Somunu {size} mm', code
    if family == 'DSG':
        return f'{model} Alüminyum Somun Gövdesi - {size} mm Mil İçin', model
    raise ValueError('Bilinmeyen aile: ' + family)


def sections(raw, code, index):
    family, size = raw['aile'], raw['nominal']
    d = {k: v['deger'] for k, v in raw['degerler'].items()}
    if family in ['KKM', 'IM']:
        finish = 'krom kaplı' if family == 'KKM' else 'indüksiyonlu'
        intro = [
            f'{code}, {size} mm çapında ve 4 metre boyunda {finish} bir doğrusal hareket milidir. Yuvarlak kesitli kılavuz yüzeyi, uygun çaplı lineer rulmanın hareket edeceği ekseni oluşturur. Buradaki çap, rulmanın mil tarafındaki nominal ölçüsüyle birlikte değerlendirilir; rulman gövdesinin dış çapı değildir. Uzun bir eksen tasarlanırken milin toplam boyu ile tablanın kullanılabilir hareket mesafesi ayrı ayrı belirlenmelidir.',
            f'Yuvarlak mil üzerinde çalışan bir eksen için {code}, {size} mm nominal çap ve 4000 mm boy seçeneğidir. Bu {finish} mil, taşıyıcı rulmanla birlikte bir doğrusal kılavuz düzeninin parçası olarak kullanılır. 4 metrelik ürün boyu, tek başına aynı uzunlukta net strok elde edileceği anlamına gelmez; uç yataklarının, bağlantıların ve hareketli gövdenin kapladığı alan projede ayrıca hesaba katılır.',
            f'{size} mm çaplı {code}, 4 metre uzunluktaki {finish} mil seçeneğini tanımlar. Milin silindirik yüzeyi üzerinde ilerleyen rulmanın iç çapı ve çalışma boşluğu, doğru eşleştirme için önemlidir. Boy ve çap iki ayrı seçim ölçüsüdür: 4000 mm stok boyu eksenin uzunlamasına yerleşimini etkilerken {size} mm çap, rulman ve mil tutucu tarafındaki nominal bağlantıyı belirler.',
        ][index % 3]
        surface = (f'{code} ürününde tanımlanan yüzey işlemi krom kaplamadır. Krom kaplama ile indüksiyonla sertleştirme aynı işlem değildir ve biri diğerinin uygulandığını tek başına göstermez. Bu mil için belirli bir HRC sertliği, kaplama kalınlığı veya çelik kalitesi verilmediğinden, yüzey işlemi adından bu değerleri çıkarmayın. Hassas geçme ya da özel ortam koşulu isteniyorsa kaplama ve sertlik beklentisi sipariş öncesinde açıkça belirtilmelidir.' if family == 'KKM' else f'{code} indüksiyonlu mil olarak seçilir; indüksiyon, krom kaplamadan farklı bir yüzey sertleştirme işlemidir. İndüksiyonlu ifadesi bu {size} mm üründe ayrıca krom kaplama bulunduğu anlamına gelmez. Belirli bir sertlik sayısı, sertleşme derinliği veya h6/g6 geçme sınıfı belirtilmemiştir. Rulmanın çalışma boşluğunu belirlerken yalnız ürün grubunun adına dayanmak yerine istenen çap toleransını ve yüzey koşulunu birlikte değerlendirin.')
        return [('Mil ve Boy Seçimi', intro), ('Yüzey İşlemi ve Eşleştirme', surface), ('Yerleşim ve Montaj', f'{code} için verilen 4000 mm boy, ara destek olmadan güvenle geçilebilecek açıklık değildir. {size} mm çapın uygulamadaki davranışı; destekler arasındaki mesafeye, yükün konumuna ve hareketli kütleye bağlıdır. İki paralel mil kullanılan bir düzende tutucuların aynı eksen yüksekliğinde ve paralel yerleşmesi gerekir. Rulman yatağını zorlayarak hizasızlığı gidermek yerine bağlantı yüzeylerini kontrol edin; montaj sırasında işlenmiş yüzeyi darbeden ve çizilmeden koruyun.'), ('Kullanım Alanları', f'{code}; otomasyon tablaları, besleme mekanizmaları, ölçüm düzenekleri ve yuvarlak mil kullanan doğrusal hareket uygulamalarında değerlendirilir. {size} mm mil çapı ile 4 metre boyun uygunluğu, istenen strok ve destek planına göre belirlenmelidir. Yalnız çap bilgisinden taşıma kapasitesi veya çalışma hızı belirlenemez. Toz, talaş ve nemin bulunduğu uygulamalarda rulmanın keçesi, yağlama düzeni ve mil üzerindeki koruyucular birlikte seçilmelidir.'), ('Bakım ve Sipariş Kontrolü', f'{code} siparişinde çapı {size} mm, boyu 4000 mm olarak karşılaştırın. Kesme ve uç işleme gereksinimini ayrı tanımlamak, stok boyu ile bitmiş parça boyunun karışmasını önler. Montaj öncesi mil boyunca darbe izi ve yüzey hasarı kontrolü yapılmalı; temizleme işlemi rulmanın yuvarlanma yüzeyine zarar vermemelidir. Yağlayıcı seçimi, kullanılan rulman ve çalışma ortamıyla birlikte ele alınır; tek bir bakım aralığı tüm eksenler için geçerli değildir.')]
    if family == 'SAC':
        length = d['Boy (L)']
        return [('Destekli Kılavuz Yapısı', f'{code}, {size} mm mil çapında ve {length} boyunda alt destekli bir doğrusal kılavuzdur. Yuvarlak milin altında boyuna uzanan destek, açık tip bir rulmanın mil üzerinde ilerleyebilmesine yönelik yerleşim sunar. Bu ürün destekli mil tarafıdır; üzerinde hareket eden lineer rulman veya araba değildir. SBR tipi destekli eksen kurarken yalnız nominal çapı değil, destek kesitini ve rulmanın alt açıklığını da birlikte karşılaştırmak gerekir.'), ('Mil, Destek ve Rulman Eşleştirmesi', f'{code} üzerinde çalışan rulman için {size} mm mil çapı ilk seçim ölçüsüdür. Bunun yanında rulmanın açıklık açısı, alt destekle temas etmeden hareket edebilmesi ve tablanın yükseklik düzeni önem taşır. Aynı çapta iki farklı destekli milin taban genişliği ya da delik aralığı aynı olmak zorunda değildir. Bu nedenle başka bir SAC veya SBR kesitinin bağlantı ölçülerini otomatik olarak bu {length} ürüne uygulamayın; mevcut makinenin bağlantı yüzeyiyle karşılaştırın.'), ('Montaj Yüzeyi ve Boy', f'{code} için {length} toplam boy, bağlantı tabanının uzunlamasına yerleşimi için esas alınır. Milin altında yer alan destek, kendi başına makinenin rijit bir yatağının yerini tutmaz; bağlanacağı yüzeyin düzgün ve yeterince desteklenmiş olması gerekir. Boy boyunca eğri bir yüzeye zorla çekilen destek, {size} mm milin rulmanla çalışma düzenini etkileyebilir. Cıvata deliklerini hazırlamadan önce gerçek taban genişliği, merkez aralıkları ve uç mesafelerini ölçmek uygun olur.'), ('Kullanım Alanları', f'{code}; CNC yardımcı eksenleri, otomasyon tablaları, malzeme besleme düzenekleri ve uzun kılavuz mesafesi gereken taşıma mekanizmaları için değerlendirilebilir. {size} mm çaplı destekli mil seçimi yapılırken yükün tabladan yüksekliği, çift kılavuz arasındaki mesafe ve hareketli rulman sayısı birlikte ele alınır. {length} boydaki bir ürünün tamamını net strok olarak kabul etmeyin; rulman gövdesi, koruyucu ve hareket sonu elemanları kullanılabilir mesafeyi azaltır.'), ('Seçim ve Bakım', f'{code} siparişinde çap ile boyu ayrı kontrol edin; aynı SAC çapında farklı boy seçenekleri bulunabilir. Rulman veya tahrik elemanı desteğin yanında ayrıca seçilir ve bu milin ürün tanımı bunları birlikte bir set olarak içermez. {size} mm yuvarlanma yüzeyinde talaş birikmesini önlemek, rulmanın yağlama noktasına erişim bırakmak ve destek bağlantılarını düzenli gözden geçirmek gerekir. Kapasite ve hassasiyet gibi sayısal sınırlar için yalnız bu {length} boy bilgisine dayanarak eksen hesabı yapılmamalıdır.')]
    if family == 'TBR':
        return [('Açık Flanşlı Gövde', f'{code}, {size} mm mil için açık flanşlı bir lineer rulman ünitesidir. Alt açıklık, destekli mil üzerinde ilerleyen gövdenin boyuna desteğin üzerinden geçebilmesine yönelik bir yapıdır. Flanşlı bağlantı yüzeyleri hareketli tablanın gövdeye bağlanmasında kullanılır. Bu ürün milin kendisi veya komple doğrusal eksen değildir; mevcut destekli mil ile gövdenin açıklığı ve yükseklik yerleşimi birlikte kontrol edilmelidir.'), ('Montaj Ölçüleri', f'{code} için W ölçüsü {d["Gövde Ölçüsü (W)"]}, L ölçüsü {d["Gövde Ölçüsü (L)"]}, B ölçüsü {d["Gövde Ölçüsü (B)"]} olarak listelenir. Bağlantı dişi {d["Bağlantı Dişi (S1)"]} değerindedir. Teknik listedeki harfler aynı TBR modelinin montaj ölçülerini ayırt eder; nominal {size} mm mil çapı, gövdenin dış ölçüsüyle karıştırılmamalıdır. Eski bir yatağın yerine takarken yalnız ürün adındaki numaraya değil, tablanın delik düzeni ve gövde için ayrılan hacme de bakın.'), ('Destekli Mil ile Çalışma', f'{code} seçilirken {size} mm çapın yanında mil desteğinin kesiti de önemlidir. Açık yapı, her destekli mil düzeninin kendiliğinden uyumlu olacağı anlamına gelmez. Gövdenin alt açıklığı ile desteğin tepe genişliği çakışmamalı; paralel iki kılavuzda bağlantı yüzeyleri birbirini zorlamamalıdır. Montaj cıvatalarını sıkmadan önce tüm strokta serbest hareketi kontrol etmek ve plakanın gövdeleri eksene dik zorlamasını önlemek gerekir.'), ('Kullanım Alanları', f'{code}; destekli yuvarlak miller kullanan taşıma tablalarında, besleme ünitelerinde, makine yardımcı eksenlerinde ve otomasyon mekanizmalarında değerlendirilen {size} mm rulman seçeneğidir. Yükün uygulama yönü, ağırlık merkezinin millerden uzaklığı ve aynı tablada kullanılan rulman adedi eksen tasarımını etkiler. Dış montaj ölçüleri tek başına güvenli taşıma yükü veya ömür hesabı vermez; kapasite hesabı rulmanın çalışma koşulları ve yağlama düzeniyle birlikte yapılmalıdır.'), ('Bakım ve Yer Değiştirme', f'{code} değişiminde mil yüzeyini, taban bağlantısını ve karşılıklı gövdelerin paralelliğini birlikte kontrol edin. {size} mm milin üzerinde aşınma, pas veya darbe izi varsa yalnız rulmanı yenilemek hareket sorununu gidermeyebilir. Yağlama noktasına erişim ve talaş koruması, bağlantı plakasının tasarımında düşünülmelidir. Montaj sonrasında kısa bir bölgede değil, çalışma strokunun tamamında sıkışma veya düzensiz direnç olup olmadığı gözden geçirilmelidir.')]
    if family in ['VM', 'SFU']:
        pitch = d['Vida Adımı (Ph)']
        if family == 'VM':
            length = d['Boy (L)']
            intro = f'{code}, {size} mm nominal çap ve {pitch} vida adımıyla tanımlanan, {length} boyunda bilyalı vidalı mildir. Bir tahrik ekseninde motorun dönme hareketi, uygun bilyalı somunla birlikte doğrusal ilerlemeye çevrilir. Burada sunulan parça mil tarafıdır; somun, somun gövdesi, kaplin ve uç yatakları ayrıca seçilir. Ürün boyu, uç işleme payı ve somunun yerleşimi hesaba katılmadan doğrudan net strok olarak kullanılmamalıdır.'
            fit = f'{code} milin {pitch} adımı, uygun tek ağızlı eşleşmede bir tam turdaki nominal ilerleme ölçüsünü tanımlar; motor kontrolündeki adım sayısıyla aynı kavram değildir. {size} mm nominal çapı eşleşen bir somun için yalnız dış çapın tutması yeterli olmaz. Bilyalı vida serisi, kanal geometrisi, dönüş yönü ve somunun sirkülasyon yapısı da dikkate alınmalıdır. {length} boydaki bu mil için ön yük veya bir hassasiyet sınıfı varsayarak konumlama hesabı yapmayın.'
            mounting = f'{code} için {length} stok boyu ile uçları işlenmiş nihai milin boyu ayrı tanımlanmalıdır. Sabit ve serbest uç yataklarının oturacağı çaplar, omuz mesafeleri ve kaplin tarafındaki bağlantı, makinenin yerleşimine göre belirlenir. {size} mm ana çapı doğrudan rulman oturma çapı kabul etmek doğru değildir. İşleme planı hazırlanırken kullanılabilir strok, somunun toplam boyu ve hareket sonu sınırları birlikte kontrol edilmelidir.'
        else:
            intro = f'{code}, {size} mm çaplı ve {pitch} adımlı bilyalı vidalı mil düzeni için bir somundur. Mil üzerindeki dönme hareketinin taşıyıcı tablaya doğrusal hareket olarak iletilmesinde görev alır. Bu parça milin kendisi veya alüminyum somun gövdesi değildir; bir araya getirilecek parçaların seri ve montaj geometrileri birlikte seçilmelidir. Sadece nominal çapın aynı olması farklı vidalı mil sistemlerinin doğrudan birbirine takılabileceği anlamına gelmez.'
            fit = f'{code} seçiminde {size} mm mil çapı ve {pitch} adım bilgisi başlangıç noktasıdır. SFU serisinde sirkülasyon sayısını belirten ekler somunun toplam boyunu değiştirebilir. Tam varyant belirtilmeden bir başka somunun L boyunu ya da flanş bağlantısını kesin eş ölçü kabul etmeyin. Mevcut makinedeki somunu değiştirirken gövde dış çapını, flanşın delik düzenini ve yağlama noktasının konumunu fiziksel parçayla karşılaştırın; yalnız modelin ilk dört rakamıyla karar vermeyin.'
            mounting = f'{code} gövdesi tablaya uygun bir bağlantı yüzeyiyle taşınmalıdır. Somunun eksenini {size} mm milin uç yataklarıyla aynı doğrultuda tutmak, bağlantının en önemli kontrollerindendir. Kaçık eksen veya eğik flanş yüzeyi cıvata sıkılarak zorla düzeltilmemelidir. Montaj sırasında milin serbest dönmesi, {pitch} adım boyunca ilerlemenin takılmadan sürmesi ve somunun hareket sonlarında mekanik sınırlara çarpmaması kontrol edilir.'
        return [('Bilyalı Tahrik Elemanı', intro), ('Çap, Adım ve Uyum', fit), ('Montaj Planı', mounting), ('Kullanım Alanları', f'{code}; konumlama tablaları, besleme mekanizmaları, CNC yardımcı eksenleri ve otomasyon sistemlerinde değerlendirilebilir. {size} mm nominal çap ile {pitch} adımın uygunluğu; hareketli kütle, ivme, hız, destek mesafesi ve istenen konumlama davranışıyla birlikte belirlenir. Bilyalı vidalı tahrik tek başına tablanın kılavuzu değildir; yanal yüklerin uygun lineer yataklarla taşınması gerekir. Nominal model kodundan güvenli çalışma yükü veya toplam sistem hassasiyeti çıkarılamaz.'), ('Yağlama ve Değişim Kontrolü', f'{code} kullanılan düzende somunun bilyaları montaj sırasında korunmalı; somun, uygun aktarım yöntemi olmadan milin ucundan çıkarılmamalıdır. {size} mm mil yüzeyindeki talaş, kir ve darbe izleri hareket kalitesini etkileyebilir. Yağlama noktası, keçeler ve koruyucular periyodik bakım planında ele alınmalıdır. {pitch} adımda çalışan bir eksenin tekrar kurulmasında bağlantılar, limit anahtarları ve düşük hızlı ilk hareket kontrolü, normal işletmeye geçmeden önce tamamlanmalıdır.')]
    if family == 'DSG':
        bore = d.get('Somun Yuva Çapı (D)')
        dimension = f'Somun yuvasının D çapı {bore} olarak listelenir; bu ölçü {size} mm nominal mil çapı değildir.' if bore else f'{size} mm mil sınıfı, gövdedeki somun yuvasının gerçek iç çapını tek başına belirtmez; D çapı ayrıca kontrol edilmelidir.'
        return [('Somun Bağlantı Gövdesi', f'{code}, {size} mm mil sınıfındaki bilyalı vida somununu hareketli tablaya bağlamak için kullanılan alüminyum bir somun gövdesidir. Kendi başına bilyalı somun, vidalı mil veya lineer rulman değildir. Mil dönme hareketini somun üzerinden iletirken bu gövde, somunun tabla tarafındaki bağlantısını kurar. Sipariş sırasında somun ile gövdeyi ayrı parçalar olarak değerlendirmek, eksik veya yanlış bileşen seçilmesini önler.'), ('Yuva ve Somun Eşleştirmesi', f'{code} için {dimension} Eşleştirmede yalnız somunun mil çapına değil, dış gövde çapına, flanş şekline ve bağlantı deliklerine de bakılır. Aynı nominal vidalı mil için farklı somun gövdeleri veya sirkülasyon boyları bulunabilir. Eski bir yuvanın yerine takılacak parçada somunun dayandığı yüzey, yağlama noktasına erişim ve montaj cıvatalarının konumu birlikte karşılaştırılmalıdır.'), ('Tabla Üzerine Montaj', f'{code} ile bağlanacak {size} mm sınıfındaki somunun ekseni, vidalı milin uç yataklarıyla aynı doğrultuda olmalıdır. Gövdenin alüminyum olması montaj yüzeyinin düzgünlüğü gereksinimini ortadan kaldırmaz. Somun, mil üzerine bindirme veya yanal zorlama oluşturmayacak şekilde yerleştirilmelidir. Bağlantı cıvatalarını sıkmadan önce tablanın tüm strok boyunca rahat hareket ettiğini kontrol edin; kaçık montajı cıvata kuvvetiyle zorlayarak gidermeyin.'), ('Kullanım Alanları', f'{code}; otomasyon eksenleri, küçük konumlama tablaları, besleme mekanizmaları ve bilyalı vidalı tahrik kullanan makine düzeneklerinde değerlendirilir. {size} mm nominal vida sınıfı tek başına gövdenin taşıma kapasitesini belirtmez. Uygulamada yükün doğrultusu, tablanın kılavuzlanması, cıvata bağlantıları ve somunun çalışma koşulları birlikte ele alınır. Lineer kılavuzların taşıması gereken yanal yükleri somun gövdesine aktarmayan bir yerleşim tercih edilmelidir.'), ('Sipariş ve Bakım Kontrolü', f'{code} alırken kullanılacak somunun tam modelini ve bağlantı yüzeyini karşılaştırın. {size} mm vidalı mil grubuna ait olduğu için her aynı çaplı somunun bu gövdeyle uyumlu olduğu varsayılmamalıdır. Yağlama deliğinin kapanmaması, cıvata başlarına erişim ve hareket sonlarında gövdenin diğer parçalara yaklaşma mesafesi kontrol edilir. İşletme sırasında gevşek bağlantı veya eksen kaçıklığı görülürse yalnız cıvataları sıkmak yerine somun ve uç yataklarının hizası da gözden geçirilmelidir.')]
    raise ValueError('Bilinmeyen aile: ' + family)


def product(raw, photo, index):
    title, code = identity(raw)
    family = raw['aile']
    specs = [(label, v['deger']) for label, v in raw['degerler'].items()]
    specs.append(('Marka', raw['marka']))
    desc = '<div class="urunAciklama"><div class="teknikDetay"><h2>' + escape(title) + '</h2>'
    for heading, paragraph in sections(raw, code, index):
        desc += '<h3>' + heading + '</h3><p>' + escape(paragraph) + '</p>'
    desc += '<h3>İlgili Ürün Grupları</h3><p>' + escape(code) + ' ile kurulacak ekseni planlarken '
    related = [('lIneer', 'lineer hareket sistemleri'), ('vidali-mil-uc-yatagi', 'vidalı mil uç yatakları')] if family in ['VM', 'SFU', 'DSG'] else [('krom-kapli-', 'yuvarlak kılavuz milleri'), ('sbr-serisi', 'SBR serisi lineer sistemler')]
    desc += ' ve '.join('<a href="' + SITE + url + '">' + label + '</a>' for url, label in related)
    desc += ' kategorilerini de inceleyebilirsiniz. Nominal ölçüyü, bağlantı yerleşimini ve ürünün tek parça kapsamını birlikte kontrol edin.</p>'
    desc += '<h3>Teknik Özellikler</h3><ul>' + ''.join('<li><strong>' + escape(k) + ':</strong> ' + escape(v) + '</li>' for k, v in specs) + '</ul></div></div>'
    terms = [code, raw['model'], title, tr_lower(title), ascii_text(title), code.replace(' ', ''), code.replace(' ', '-'), re.sub(r'([A-Za-zİ]+)(\d)', r'\1 \2', code), f'{raw["nominal"]} mm', f'{raw["nominal"]}mm']
    terms += {'KKM': ['krom kaplı mil', 'krom kapli mil', 'linear shaft', '4 metre mil', '4000 mm mil'], 'IM': ['indüksiyonlu mil', 'induksiyonlu mil', 'hardened linear shaft', '4 metre mil', '4000 mm mil'], 'SAC': ['alt destekli mil', 'supported linear shaft', 'destekli ray'], 'TBR': ['açık flanşlı lineer rulman', 'acik flansli lineer rulman', 'open linear bearing'], 'VM': ['vidalı mil', 'vidali mil', 'ball screw shaft'], 'SFU': ['bilyalı somun', 'bilyali somun', 'ball screw nut', 'vidalı mil somunu', 'vidali mil somunu'], 'DSG': ['alüminyum somun gövdesi', 'aluminyum somun govdesi', 'ball nut housing']}[family]
    words = ', '.join(dict.fromkeys(terms))
    brief = title + '. Ölçüleri, montaj seçimini ve kullanım alanlarını inceleyin.'
    category = 'LİNEER>' + CATEGORIES[family][0]
    item = dict(kod=raw['kod'], URUNADI=title, MARKA=raw['marka'], KATEGORI=category, EK_KATEGORILER=[], yeni_kategori=False, ONYAZI=table(specs), ACIKLAMA=desc, ANAHTARKELIME=words, SEO_SAYFABASLIK=title, SEO_SAYFAACIKLAMA=brief, SEO_ANAHTARKELIME=words, resim='gorseller/' + slug(title) + '.jpg', resim_seviye=photo['seviye'], resim_kaynak=photo['url'], teknik_kaynak=list(dict.fromkeys(v['kaynak'] for v in raw['degerler'].values())), bayraklar=raw['bayraklar'])
    ctx = dict(kod=raw['kod'], title=title, path='/' + slug(title), productId=index + 1, crumbs=['Anasayfa'] + category.split('>'), specs=[dict(l=k, v=v) for k, v in specs], onyazi=[dict(l=k, v=v) for k, v in specs], cizim_modulu='mil' if family in ['KKM', 'IM'] else None)
    return item, ctx
